--- a/api-sheriff/src/main/java/de/cuioss/sheriff/gateway/bff/reserved/ClientJwksEndpoint.java
+++ b/api-sheriff/src/main/java/de/cuioss/sheriff/gateway/bff/reserved/ClientJwksEndpoint.java
